-- Ruby Slots submissions. Contact data is private: only the Netlify Functions
-- (service_role) can read or write this table.

create table public.game_submissions (
  id uuid primary key default gen_random_uuid(),
  -- Generated by the browser when a round ends; makes retries idempotent.
  attempt_id uuid not null unique,
  game_id text not null check (game_id in ('ruby-slots')),
  player_name text not null check (char_length(player_name) between 1 and 40),
  email text not null check (
    char_length(email) between 3 and 254
    and email ~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$'
  ),
  score integer not null check (score >= 0),
  marketing_opt_in boolean not null default false,
  -- Submission requires the consent checkbox, so consent time = submission time.
  created_at timestamptz not null default now()
);

create index game_submissions_game_created_idx on public.game_submissions (game_id, created_at desc);

alter table public.game_submissions enable row level security;
-- No policies: anon and authenticated roles get nothing.
revoke all on public.game_submissions from anon, authenticated;

-- Start of the current day at the conference (IST).
create or replace function public.event_day_start()
returns timestamptz
language sql
stable
set search_path = ''
as $$
  select date_trunc('day', now() at time zone 'Asia/Kolkata') at time zone 'Asia/Kolkata';
$$;

-- Today's leaderboard: each player's (by email) best score. Returns names and scores only.
create or replace function public.daily_top_scores(p_game_id text, p_limit integer default 10)
returns table (player_name text, score integer)
language sql
stable
set search_path = ''
as $$
  select best.player_name, best.score
  from (
    select distinct on (lower(s.email)) s.player_name, s.score, s.created_at
    from public.game_submissions s
    where s.game_id = p_game_id
      and s.created_at >= public.event_day_start()
    order by lower(s.email), s.score desc, s.created_at asc
  ) best
  order by best.score desc, best.created_at asc
  limit least(greatest(p_limit, 1), 50);
$$;

-- Where a score would land on today's board: 1 + players whose best today is higher.
create or replace function public.daily_rank(p_game_id text, p_score integer)
returns integer
language sql
stable
set search_path = ''
as $$
  select 1 + count(*)::integer
  from (
    select max(s.score) as best
    from public.game_submissions s
    where s.game_id = p_game_id
      and s.created_at >= public.event_day_start()
    group by lower(s.email)
  ) players
  where players.best > p_score;
$$;

revoke all on function public.event_day_start() from public, anon, authenticated;
revoke all on function public.daily_top_scores(text, integer) from public, anon, authenticated;
revoke all on function public.daily_rank(text, integer) from public, anon, authenticated;
grant execute on function public.event_day_start() to service_role;
grant execute on function public.daily_top_scores(text, integer) to service_role;
grant execute on function public.daily_rank(text, integer) to service_role;
